import sys
class Porter:
    def __init__(self,w):
        self.b=list(w.lower()); self.k=len(w)-1; self.j=0; self.p1=0
    def cons(self,i):
        c=self.b[i]
        if c in 'aeiou': return False
        if c=='y': return True if i==0 else not self.cons(i-1)
        return True
    def m(self):
        n=0; i=0
        while True:
            if i>self.j: return n
            if not self.cons(i): break
            i+=1
        i+=1
        while True:
            while True:
                if i>self.j: return n
                if self.cons(i): break
                i+=1
            i+=1; n+=1
            while True:
                if i>self.j: return n
                if not self.cons(i): break
                i+=1
            i+=1
    def vowelinstem(self):
        for i in range(self.j): 
            if not self.cons(i): return True
        return False
    def doublec(self,k):
        if k<1: return False
        if self.b[k]!=self.b[k-1]: return False
        return self.cons(k)
    def cvc(self,i):
        if i<0 or not self.cons(i): return False
        if i==0: return False
        if self.cons(i-1): return False
        if i==1: return False
        if not self.cons(i-2): return False
        c=self.b[i]
        if c in 'wxy': return False
        return True
    def ends(self,s):
        l=len(s)
        if l>self.k+1: return False
        if self.b[self.k-l+1:self.k+1]!=list(s): return False
        self.j=self.k-l
        return True
    def setto(self,s):
        l=len(s); self.b=self.b[:self.j+1]+list(s); self.k=self.j+l
    def r(self,s):
        if self.m()>0: self.setto(s)
    def step1ab(self):
        if self.ends("sses"): self.r("ss")
        elif self.ends("ies"): self.r("i")
        elif self.ends("ss"): pass
        elif self.ends("s"): self.r("")
        if self.ends("eed"): 
            if self.m()>0: self.k=self.j+2
        elif (self.ends("ed") or self.ends("ing")) and self.vowelinstem():
            self.k=self.j
            if self.ends("at"): self.setto("ate")
            elif self.ends("bl"): self.setto("ble")
            elif self.ends("iz"): self.setto("ize")
