class P:
    def __init__(self,w):
        self.b=list(w.lower()); self.k=len(w)-1; self.j=0
    def cons(self,i):
        c=self.b[i]
        if c in VOWELS: return False
        if c=='y': return True if i==0 else not self.cons(i-1)
        return True
    def m(self,j=None):
        if j is None: j=self.j
        n=0; i=0
        while True:
            if i>j: return n
            if not self.cons(i): break
            i+=1
        i+=1
        while True:
            while True:
                if i>j: return n
                if self.cons(i): break
                i+=1
            i+=1; n+=1
            while True:
                if i>j: return n
                if not self.cons(i): break
                i+=1
            i+=1
    def vowelinstem(self,j):
        for i in range(j+1):
            if not self.cons(i): return True
        return False
    def doublec(self,kk):
        if kk<1: return False
        if self.b[kk]!=self.b[kk-1]: return False
        return self.cons(kk)
    def cvc(self,i):
        if i<2: return False
        if not self.cons(i): return False
        if self.cons(i-1): return False
        if not self.cons(i-2): return False
        if self.b[i] in 'wxy': return False
        return True
    def ends(self,s):
        l=len(s)
        if l>self.k+1: return False
        if self.b[self.k-l+1:self.k+1]!=list(s): return False
        self.j=self.k-l
        return True
    def setto(self,s):
        self.b=self.b[:self.j+1]+list(s); self.k=self.j+len(s)
    def r(self,s):
        if self.m(self.j)>0: self.setto(s); return True
        return False
    def step1a(self):
        if self.ends("sses"): self.r("ss"); return
        if self.ends("ies"): self.r("i"); return
        if self.ends("ss"): return
        if self.ends("s"): self.r("")
    def step1b(self):
        if self.ends("eed"):
            if self.m(self.j)>0: self.setto("ee")
            return
        if (self.ends("ed") or self.ends("ing")) and self.vowelinstem(self.j):
            self.k=self.j
            if self.ends("at"): self.setto("ate"); return
            if self.ends("bl"): self.setto("ble"); return
            if self.ends("iz"): self.setto("ize"); return
            if self.doublec(self.k):
                self.k-=1
                if self.b[self.k] in 'lsz': self.k+=1
                return
            if self.m(self.k)==1 and self.cvc(self.k): self.setto("e")
    def step1c(self):
        if self.ends("y") and self.vowelinstem(self.j): self.b[self.k]='i'
    def step2(self):
