               ("bli","ble"),("alli","al"),("entli","ent"),("eli","e"),("ousli","ous"),("ization","ize"),
               ("ation","ate"),("ator","ate"),("alism","al"),("aliti","al"),("alit","al"),
               ("aliti","al"),("alit","al"),("ational","ate"),("tional","tion")]
        for suf,rep in rules:
            if self.ends(suf) and self.r(rep): return
    def step3(self):
        for suf,rep in [("icate","ic"),("ative",""),("alize","al"),("iciti","ic"),("ical","ic"),("ful",""),("ness","")]:
            if self.ends(suf) and self.r(rep): return
    def step4(self):
        for suf in ["al","ance","ence","er","ic","able","ible","ant","ement","ment","ent","ion","ou","ism","ate","iti","ous","ive","ize"]:
            if self.ends(suf):
                if self.m(self.j)>1:
                    if suf in ("ion","ou") and self.b[self.j] in 'st': pass
                    else: self.k=self.j
                return
    def step5a(self):
        if self.b[self.k]=='e':
            self.j=self.k-1
            a=self.m()
            if a>1 or (a==1 and not self.cvc(self.k-1)): self.k-=1
    def step5b(self):
        if self.b[self.k]=='l' and self.doublec(self.k):
            self.j=self.k-1
            if self.m()>1: self.k-=1
    def stem(self):
        if self.k<=1: return "".join(self.b[:self.k+1])
        self.step1a(); self.step1b(); self.step1c(); self.step2(); self.step3(); self.step4(); self.step5a(); self.step5b()
        return "".join(self.b[:self.k+1])
