package main

import (
	"bytes"
	"go/doc"
	"fmt"
)

func formatTwoColumns(w *bytes.Buffer, indent, padding, width int, rows [][2]string) {
	s := 0
	for _, row := range rows {
		if c := len(row[0]); c > s && c < 30 {
			s = c
		}
	}
	indentStr := bytes.Repeat([]byte(" "), indent)
	pad := bytes.Repeat([]byte(" "), padding)
	for _, row := range rows {
		buf := bytes.NewBuffer(nil)
		doc.ToText(buf, row[1], "", string(pad), width-s-padding-indent)
		lines := bytes.Split(bytes.TrimRight(buf.Bytes(), "\n"), []byte("\n"))
		fmt.Fprintf(w, "%s%-*s%*s", indentStr, s, row[0], padding, "")
		if len(row[0]) >= 30 {
			fmt.Fprintf(w, "\n%s%s", indentStr, string(pad))
		}
		fmt.Fprintf(w, "%s\n", lines[0])
		for _, line := range lines[1:] {
			fmt.Fprintf(w, "%s%s%s\n", indentStr, bytes.Repeat([]byte(" "), s+padding), line)
		}
	}
}

func main() {
	rows := [][2]string{
		{"-h, --help", "Show context-sensitive help."},
		{"    --notebook-dir=PATH", "Turn off notebook auto-discovery and set manually the notebook where commands are run."},
		{"-W, --working-dir=PATH", "Run as if zk was started in <PATH> instead of the current working directory."},
		{"    --no-input", "Never prompt or ask for confirmation."},
	}
	var b bytes.Buffer
	formatTwoColumns(&b, 2, 4, 80, rows)
	fmt.Print(b.String())
	fmt.Println("----")
	args := [][2]string{{"[<path> ...]", "Find notes matching the given path, including its descendants."}}
	b2 := bytes.NewBuffer(nil)
	formatTwoColumns(b2, 2, 4, 80, args)
	fmt.Print(b2.String())
	fmt.Println("----")
	// list flags formatting group
	lrows := [][2]string{
		{"-f, --format=TEMPLATE", "Pretty print the list using a custom template or one of the predefined formats: oneline, short, medium, long, full, json, jsonl."},
		{"    --header=STRING", "Arbitrary text printed at the start of the list."},
		{"    --footer=\"\\n\"", "Arbitrary text printed at the end of the list."},
		{"-d, --delimiter=\"\\n\"", "Print notes delimited by the given separator."},
		{"-0, --delimiter0", "Print notes delimited by ASCII NUL characters. This is useful when used in conjunction with `xargs -0`."},
		{"-P, --no-pager", "Do not pipe output into a pager."},
