		{"    --mention=PATH,...", "Find notes mentioning the title of the given ones."},
		{"    --mentioned-by=PATH,...", "Find notes whose title is mentioned in the given ones."},
	}
	b3 := bytes.NewBuffer(nil)
	formatTwoColumns(b3, 2, 4, 80, lrows)
